select case when d.budget >= 3621000 then 'high' when d.budget >= 1385000 then 'mid' else 'low' end as budget_bucket, d.location, round(stddev(e.salary), 2) as stddev_salary, max(e.salary) - min(e.salary) as salary_range from employees e inner join departments d on d.id = e.dept_id group by case when d.budget >= 3621000 then 'high' when d.budget >= 1385000 then 'mid' else 'low' end, d.location order by budget_bucket, location limit 20;
